function output = heartlib()
% output = heartlib()
%
%    f(x) = {x if x > 0
%                               -x otherwise where x: ℝ 
    function [ret] = f(x)
        assert(numel(x) == 1);

        if x > 0
            ret = x;
        else
            ret = -x;
        end
    end

    output.f = @f;
end

